function seed(){const customers=[{id:'DEMO-AVATA',name:'AVATA',currency:'MYR'},{id:'DEMO-BERJAYA',name:'BERJAYA',currency:'MYR'},{id:'DEMO-DUDU',name:'DUDU',currency:'MYR'},{id:'DEMO-ALPHA',name:'ALPHA RETAIL',currency:'MYR'}];const today=new Date();today.setHours(11,35,0,0);const tasks=[];for(let i=0;i<30;i++){let p=products[i%10];const done=Array(9).fill(false);done[0]=i>=3&&i<8;tasks.push({id:`T-AV-${String(i+1).padStart(4,'0')}`,customerId:'DEMO-AVATA',orderId:'O-AV-012',barcode:p[0],name:p[1],packing:p[2],ord:[50,20,30,40,20][i%5],requested:[50,20,30,40,20][i%5],inc:null,supplier:i%10<3?'Supplier A':`Supplier ${['B','C','D','E','F'][i%5]}`,price:['1.42','25.56','2.00%','0.00%','0'],po:done[0]?'NC-PO-012':'',done,archived:false,risk:null,wasRisk:false,seq:i,receivedAt:today.toISOString(),updatedAt:today.toISOString(),updatedBy:'Law',history:[{kind:'Order received',at:today.toISOString(),by:'Law',detail:'采购意向接入 · 示例'}]});if(done[0]){tasks.at(-1).history.push({kind:'PO merged',at:new Date(today.getTime()+600000).toISOString(),by:'Yeoyo',detail:'NC-PO-012'});tasks.at(-1).updatedAt=new Date(today.getTime()+600000).toISOString();tasks.at(-1).updatedBy='Yeoyo';}}
for(let i=0;i<3;i++){let p=products[i];const done=[true,true,true,true,i!==1,false,false,false,false];tasks.push({id:`T-BJ-${i+1}`,customerId:'DEMO-BERJAYA',orderId:'O-BJ-008',barcode:p[0],name:p[1],packing:p[2],ord:50,requested:50,inc:i===0?40:null,supplier:'Supplier A',price:['1.42','25.56','2.00%','0.00%','0'],po:'NC-PO-008',done,archived:false,risk:i===0?{reason:'Supplier short delivery / 供应商少送',note:'供应商预计下批补送10箱。'}:null,wasRisk:i===0,seq:i,receivedAt:today.toISOString(),updatedAt:today.toISOString(),updatedBy:'Hia',history:[{kind:'Order received',at:today.toISOString(),by:'Law',detail:'原始订单50 CTN'},...(i===0?[{kind:'Incoming Qty Confirmed',at:new Date(today.getTime()+1800000).toISOString(),by:'Hia',detail:'ord 50 / inc 40 · Risk'}]:[])]});}
return {customers,tasks,paymentRequests:[{id:'PAY-001',po:'NC-PO-008',customerId:'DEMO-BERJAYA',amount:1000,paid:600,currency:'MYR',urgent:false,reason:''},{id:'PAY-002',po:'NC-PO-008',customerId:'DEMO-BERJAYA',amount:400,paid:0,currency:'MYR',urgent:true,reason:'供应商要求尽快安排余款。'}]};}
