let lastSaved=structuredClone(db);
let view='dashboard',customerId='DEMO-AVATA',selected=new Set(),filter={query:'',supplier:'',order:'',stage:'',risk:false},drafts=new Map(),sequenceDraft=null,held=null,highlightTimer,toastTimer,dragId=null;
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),content=document.querySelector('#dialogContent');
let draftCacheFailure='',restoredDraft=false,formContext=null,formDraft=null,recoveryConflict=null,restoringCache=false;
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
const active=()=>db.tasks.filter(t=>!t.archived);const scope=()=>active().filter(t=>t.customerId===customerId).sort((a,b)=>a.seq-b.seq);const find=id=>db.tasks.find(t=>t.id===id);
function persist(){const saved=structuredClone(db);if(sequenceDraft)sequenceDraft.forEach((id,i)=>{const t=saved.tasks.find(t=>t.id===id);if(t)t.seq=i;});try{localStorage.setItem(STORAGE,JSON.stringify(saved));lastSaved=saved;return true;}catch{db=structuredClone(lastSaved);toast('本地保存失败，输入保留；请重试或取消。');return false;}}function now(){return new Date().toISOString();}function event(t,kind,detail){const at=now();t.history.push({kind,detail,at,by:'Law'});t.updatedAt=at;t.updatedBy='Law';}
function toast(message){if(view==='room'&&(drafts.size||sequenceDraft)&&document.querySelector('#saveNotice')){updateSaveNotice(message);return;}const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4500);}
function updateSaveNotice(message){const el=document.querySelector('#saveNotice');if(el){el.hidden=!(drafts.size||sequenceDraft||formDraft||draftCacheFailure||recoveryConflict);document.querySelector('#saveNoticeText').textContent=message||draftCacheFailure||(recoveryConflict?'旧草稿与当前资料不同，已保留待核对':restoredDraft?'已恢复草稿 · 尚未提交':'草稿已保留 · 尚未提交');el.querySelector('#reviewDraftCache')?.remove();if(recoveryConflict){const b=document.createElement('button');b.id='reviewDraftCache';b.className='btn';b.textContent='查看草稿';el.append(b);}}const footer=content.querySelector('.dialogfoot>.muted');if(footer&&formDraft)footer.textContent=draftCacheFailure||'草稿已保留 · 尚未提交';}
function taskDraftBase(t){return JSON.stringify([t.price,t.supplier,t.priceBasis||'ctn',t.po,t.ord,t.inc,t.risk]);}
function setFormContext(kind,id,ids=[]){formContext={kind,id,customerId,selected:[...selected],bases:(ids.length?ids:id?[id]:[]).map(key=>[key,taskDraftBase(find(key))])};}
function captureFormDraft(){if(restoringCache||!modal.open||!formContext)return;const fields={};content.querySelectorAll('input:not([readonly]),textarea,select').forEach(el=>{if(el.id)fields[el.id]=el.value;});if(formContext.kind==='special'&&fields.specialSource!==formContext.id){formContext.id=fields.specialSource;formContext.bases=[[formContext.id,taskDraftBase(find(formContext.id))]];}formDraft={...formContext,fields};restoredDraft=false;saveDraftCache();}
function saveDraftCache(){if(restoringCache)return true;if(recoveryConflict){updateSaveNotice();return false;}try{if(!drafts.size&&!sequenceDraft&&!formDraft)localStorage.removeItem(DRAFT_STORAGE);else localStorage.setItem(DRAFT_STORAGE,JSON.stringify({v:1,customerId,entries:[...drafts],order:sequenceDraft?{base:[...sequenceDraft],ids:scope().map(t=>t.id)}:null,form:formDraft,savedAt:now()}));draftCacheFailure='';}catch{draftCacheFailure='草稿保留失败，请先保存再关闭页面';}updateSaveNotice();return !draftCacheFailure;}
function dropFormDraft(){formContext=null;formDraft=null;saveDraftCache();}
function restoreDraftCache(){let raw;try{raw=localStorage.getItem(DRAFT_STORAGE);if(!raw)return;const cache=JSON.parse(raw);if(cache.v!==1||!db.customers.some(c=>c.id===cache.customerId)||!Array.isArray(cache.entries))throw Error();customerId=cache.customerId;view='room';const rows=active().filter(t=>t.customerId===cache.customerId).sort((a,b)=>a.seq-b.seq),entryValid=cache.entries.every(([id,d])=>{const t=find(id);return t&&!t.archived&&t.customerId===cache.customerId&&Array.isArray(d.price)&&d.price.length===5&&d.base===taskDraftBase(t);});const orderValid=!cache.order||(JSON.stringify(cache.order.base)===JSON.stringify(rows.map(t=>t.id))&&cache.order.ids.length===rows.length&&new Set(cache.order.ids).size===rows.length&&cache.order.ids.every(id=>rows.some(t=>t.id===id)));const formValid=!cache.form||(cache.form.customerId===cache.customerId&&Array.isArray(cache.form.selected)&&Array.isArray(cache.form.bases)&&cache.form.fields&&typeof cache.form.fields==='object'&&['po','qty','risk','special','move'].includes(cache.form.kind)&&cache.form.bases.every(([id,base])=>find(id)&&find(id).customerId===cache.customerId&&taskDraftBase(find(id))===base));if(!entryValid||!orderValid||!formValid){recoveryConflict={raw,cache};return;}customerId=cache.customerId;drafts=new Map(cache.entries);if(cache.order){sequenceDraft=cache.order.base;cache.order.ids.forEach((id,i)=>find(id).seq=i);}formDraft=cache.form;view='room';restoredDraft=!!(drafts.size||sequenceDraft||formDraft);}catch{if(raw){recoveryConflict={raw};view='room';}}}
function restoreFormDraft(){if(!formDraft||recoveryConflict)return;const cached=structuredClone(formDraft);restoringCache=true;try{selected=new Set(cached.selected.filter(id=>find(id)?.customerId===customerId));renderRoom();if(cached.kind==='po')openPo(cached.id);else if(cached.kind==='qty')qtyDialog(cached.id);else if(cached.kind==='risk')riskDialog(cached.id);else if(cached.kind==='special')specialDialog();else moveDialog();for(const [id,value]of Object.entries(cached.fields)){const el=content.querySelector('#'+id);if(el){el.value=value;if(el.tagName==='SELECT'||id==='specialQty')el.dispatchEvent(new Event(el.tagName==='SELECT'?'change':'input',{bubbles:true}));}}formDraft=cached;}finally{restoringCache=false;}updateSaveNotice();}
function reviewDraftCache(){const cache=recoveryConflict.cache,labels={poNumber:'P.O. Number',specialSource:'来源任务',specialQty:'Extra Qty',specialReason:'Reason',qtyValue:'Order Qty',qtyReason:'Reason',riskReason:'Risk Reason',riskNote:'Note',moveTarget:'排列位置'};const prices=cache?.entries?.length?`<table class="rowlist"><thead><tr><th>产品 / Task</th><th>保留的输入</th></tr></thead><tbody>${cache.entries.map(([id,d])=>`<tr><td>${esc(find(id)?.name||id)}<small>${esc(id)}</small></td><td>${['LP/Pc','LP/Ctn','Disc.1','Disc.2','Disc.3'].map((label,i)=>`${label}: ${esc(d.price[i])}`).join('<br>')}<br>Supplier: ${esc(d.supplier)}</td></tr>`).join('')}</tbody></table>`:'';const form=cache?.form?`<div class="note">${Object.entries(cache.form.fields).map(([id,v])=>`${esc(labels[id]||id)}: ${esc(v)}`).join('<br>')}</div>`:'';const order=cache?.order?`<div class="note">草稿排列：${cache.order.ids.map(id=>esc(find(id)?.name||id)).join(' → ')}</div>`:'';openDialog('保留的草稿 / Retained draft','当前已保存资料保持不变',`<div class="note">此草稿与当前资料不同，未自动套用。请先核对需要的内容，再决定是否放弃旧草稿。</div>${prices}${form}${order}${!cache?'<div class="note">草稿暂时无法读取，原内容仍保留在当前浏览器。</div>':''}`,'<button class="btn" id="dialogSave">放弃旧草稿</button>',()=>{try{localStorage.removeItem(DRAFT_STORAGE);recoveryConflict=null;draftCacheFailure='';closeDialog();saveDraftCache();renderRoom();}catch{error('草稿清理失败，原草稿仍保留。');}});}
// Shipment date is not connected yet; no fictional date or customer-wide date is inferred.
function shipmentSummary(rows){const ids=[...new Set(rows.map(t=>t.orderId))];return `<span class="shipment-summary"><svg viewBox="0 0 20 20" aria-hidden="true"><rect x="3" y="4" width="14" height="13" rx="2"/><path d="M3 8h14M6 2v4M14 2v4"/></svg><span>Est. Shipment Date</span><b>—</b>${ids.length>1?`<button class="shipment-orders" data-shipment="${rows[0].customerId}">${ids.length} Orders</button>`:'<small>未提供</small>'}</span>`;}
function shipmentDatesDialog(cid){const rows=active().filter(t=>t.customerId===cid),ids=[...new Set(rows.map(t=>t.orderId))];openDialog('Est. Shipment Date','按订单分别显示',`<table class="rowlist"><thead><tr><th>Order ID</th><th>Est. Shipment Date</th></tr></thead><tbody>${ids.map(id=>`<tr><td>${esc(id)}</td><td>— · 未提供</td></tr>`).join('')}</tbody></table>`);}
function fullDate(at){const d=new Date(at),pad=n=>String(n).padStart(2,'0');return `${pad(d.getDate())}-${pad(d.getMonth()+1)}-${String(d.getFullYear()).slice(-2)} ${pad(d.getHours())}:${pad(d.getMinutes())}`;}
function shortDate(at,by){const d=new Date(at),today=new Date(),label=d.toDateString()===today.toDateString()?'Today':fullDate(at).split(' ')[0];return `${label} ${String(d.getHours()).padStart(2,'0')}.${String(d.getMinutes()).padStart(2,'0')} fr ${by}`;}
function unfinished(t,i){return !t.done[i];}function next(t){return t.done.findIndex((x,i)=>i!==4&&!x);}function counts(rows){return stages.map((_,i)=>rows.filter(t=>unfinished(t,i)).length);}
function costResult(values,ea,basis='ctn'){let b;if(basis==='pc'){if(!Number.isFinite(Number(ea))||Number(ea)<=0||!validatePrice(values[0],0))return {b:null,f:null};b=Number(ea)*Number(values[0]);}else{if(!validatePrice(values[1],1))return {b:null,f:null};b=Number(values[1]);}if(!values.slice(2).every((v,i)=>validatePrice(v,i+2)))return {b,f:null};const f=b*(1-parseFloat(values[2])/100)*(1-parseFloat(values[3])/100)-Number(values[4]);return {b:Math.round((b+Number.EPSILON)*100)/100,f:Math.round((f+Number.EPSILON)*100)/100};}
function priceBasis(t){return drafts.get(t.id)?.priceBasis||t.priceBasis||'ctn';}
function refreshCost(id){const t=find(id),r=costResult(price(t),t.ea,priceBasis(t)),row=document.querySelector(`tr[data-id="${id}"]`);if(!row)return;const b=row.querySelector('[data-field="1"]');if(b&&priceBasis(t)==='pc')b.value=r.b===null?'—':r.b.toFixed(2);const net=row.querySelector('.net');net.textContent=r.f===null?'—':r.f.toFixed(2);net.classList.toggle('negative',r.f!==null&&r.f<0);if(drafts.has(id)&&priceBasis(t)==='pc')drafts.get(id).price[1]=r.b===null?'':r.b.toFixed(2);}
function price(t){return drafts.get(t.id)?.price||t.price;}function supplier(t){return drafts.get(t.id)?.supplier??t.supplier;}
function matching(){return scope().filter(t=>(!filter.query||[t.barcode,t.name,t.id,t.po,t.orderId].join(' ').toLowerCase().includes(filter.query.toLowerCase()))&&(!filter.supplier||supplier(t)===filter.supplier)&&(!filter.order||t.orderId===filter.order)&&(filter.stage===''||unfinished(t,Number(filter.stage)))&&(!filter.risk||t.risk));}
const visibleStageIndexes=[0,1,2,3,5,6,8];
// GP is a read-only CMS projection; this room does not calculate profit.
function projectedGp(t){return t.gp==null||String(t.gp).trim()===''?null:Number.isFinite(Number(t.gp))?Number(t.gp):null;}
function gpMarkup(t){const gp=projectedGp(t);return gp===null?'—':esc(t.gp);}
function rowNumber(id){return String(scope().findIndex(t=>t.id===id)+1).padStart(3,'0');}
function riskSummary(){const rows=scope().filter(t=>projectedGp(t)!==null&&projectedGp(t)<0||t.risk);openDialog('RISK / 高风险交易',`${rows.length} rows`,rows.length?`<table class="rowlist"><thead><tr><th style="width:12%">Row</th><th>DESCRIPTION</th><th style="width:17%">GP</th><th style="width:27%">RISK</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${rowNumber(t.id)}</td><td><b>${esc(t.name)}</b><small>${esc(t.barcode)}</small></td><td class="${projectedGp(t)!==null&&projectedGp(t)<0?'negative':''}">${gpMarkup(t)}</td><td>${[projectedGp(t)!==null&&projectedGp(t)<0?'Negative GP / 负利润':'',t.risk?'Receipt Risk / 来货差异':''].filter(Boolean).join('<br>')}</td></tr>`).join('')}</tbody></table>`:'<div class="note">目前没有已知的高风险交易。<br>No known high-risk rows.</div>');}
function customerName(c){return c.id==='DEMO-AVATA'?'AVATA TRADING PTE LTD':c.name;}
function receivedMarkup(t){const by=t.history.find(e=>e.kind==='Order received')?.by||'Law';return `<div class="date">${shortDate(t.receivedAt,by).split(' fr ')[0]}</div><small>fr ${esc(by.toUpperCase())}</small>`;}
function stageIcon(i){const icons={"0":"<path d=\"M7 3h12l6 6v22H7zM19 3v7h6\"/><text x=\"16\" y=\"22\" text-anchor=\"middle\">P.O.</text>","1":"<path d=\"M7 3h12l6 6v22H7zM19 3v7h6M11 23h10M11 27h7\"/><text x=\"16\" y=\"18\" text-anchor=\"middle\">INV</text>","2":"<rect x=\"6\" y=\"7\" width=\"21\" height=\"24\" rx=\"2\"/><rect x=\"12\" y=\"3\" width=\"9\" height=\"7\" rx=\"2\" fill=\"white\"/><path d=\"m11 20 4 4 8-9\"/>","3":"<rect x=\"3\" y=\"8\" width=\"30\" height=\"20\" rx=\"1\"/><circle cx=\"18\" cy=\"18\" r=\"7\"/><text x=\"18\" y=\"23\" text-anchor=\"middle\" style=\"font-size:15px\">$</text>","5":"<path d=\"m13 11 10-6 10 6zM14 29h19M16 14v10M23 14v10M30 14v10M2 21h17m-5-5 5 5-5 5\"/>","6":"<path d=\"m8 7 10-4 10 4-10 4zM8 7v9l10 4 10-4V7M18 11v9M8 17v9l10 4 10-4v-9M18 21v9M5 30h26v3H5zM8 33v2M28 33v2\"/>","8":"<path d=\"M3 8h18v17H3zM21 14h6l5 6v5H21M27 14v7h5\"/><circle cx=\"9\" cy=\"27\" r=\"3\" fill=\"white\"/><circle cx=\"26\" cy=\"27\" r=\"3\" fill=\"white\"/><path d=\"M6 15h11m-3-3 3 3-3 3\"/>"};return `<svg class="stage-icon" viewBox="0 0 36 36" aria-hidden="true">${icons[i]||''}</svg>`;}
function track(rows){return `<section class="track" aria-label="Pending workload">${visibleStageIndexes.map(i=>{const n=counts(rows)[i];return `<div class="trackitem">${stageIcon(i)}<button class="circle ${n===0?'zero':''}" data-hold="${i}" aria-label="${stages[i][0]} ${n}">${n}</button><span class="tracklabel"><span>${stages[i][0]}<small>${stages[i][1]}</small></span></span></div>`;}).join('')}</section>`;}
function heading(title,sub,buttons=''){return `<div class="heading"><div><div class="eyebrow">PURCHASE / ${view.toUpperCase()}</div><h1>${title}</h1><span class="muted">${sub}</span></div><div class="actions">${buttons}</div></div>`;}
function metrics(rows){return `<section class="metrics"><div class="metric"><span>Active Orders / 进行中订单</span><b>${new Set(rows.map(t=>t.orderId)).size}</b><small class="muted">不同 Order ID</small></div><div class="metric"><span>Purchase Tasks / 采购任务</span><b>${rows.length}</b><small class="muted">产品行任务 ID</small></div><div class="metric"><span>Unpaid Requests / 未完成付款申请</span><b>${db.paymentRequests.filter(p=>p.paid<p.amount).length}</b><small class="muted">每次申请独立</small></div><div class="metric red"><span>Receipt Risk / 来货问题</span><b>${rows.filter(t=>t.risk).length}</b><small class="muted">有问题的产品行</small></div></section>`;}
function customerTable(){return `<table class="directory"><thead><tr><th style="width:30%">Customer / 客户</th><th style="width:27%">Est. Shipment Date</th><th>Tasks / 任务</th><th>Orders / 订单</th><th>Risk</th><th></th></tr></thead><tbody>${db.customers.map(c=>{const rows=active().filter(t=>t.customerId===c.id);return `<tr><td><button class="customerlink" data-customer="${c.id}">${c.name}</button></td><td>${rows.length?shipmentSummary(rows):'—'}</td><td>${rows.length?`<span class="bubble">${rows.length}</span>`:'0'}</td><td>${new Set(rows.map(t=>t.orderId)).size}</td><td>${rows.filter(t=>t.risk).length||'—'}</td><td><button class="btn" data-customer="${c.id}">Open Room →</button></td></tr>`;}).join('')}</tbody></table>`;}
function render(){updateCompanyHeader();clearHold();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(view==='dashboard'||view==='customers'){renderDashboard();}
else if(view==='room')renderRoom();else if(view==='po')renderPo();else if(view==='payments')renderPayments();else renderHistory();}
function renderRoom(){const c=db.customers.find(c=>c.id===customerId),rows=scope(),shown=matching(),suppliers=[...new Set(rows.map(t=>supplier(t)))],orders=[...new Set(rows.map(t=>t.orderId))];app.innerHTML='<section class="roomhead">'+heading(customerName(c),`<span class="room-company">${companyCode} · Purchase Room</span><span class="room-counts">Tasks <b>${rows.length}</b>　Suppliers <b>${suppliers.length}</b></span>`+shipmentSummary(rows))+track(rows)+'</section>'+`<div class="tools"><select id="supplierFilter"><option value="">All Supplier</option>${suppliers.map(s=>`<option value="${esc(s)}" ${filter.supplier===s?'selected':''}>${esc(supplierName(s))}</option>`).join('')}</select><select id="stageFilter"><option value="">Waiting List</option>${stages.map((s,i)=>i===4?'':`<option value="${i}" ${String(i)===filter.stage?'selected':''}>${s[0]}</option>`).join('')}</select><button class="btn risk-summary" id="riskFilter"><span class="risk-icon" aria-hidden="true">▲<b>!</b></span> Risk</button><span class="tool-divider" aria-hidden="true"></span><button class="btn special-button" id="specialPurchase"><span aria-hidden="true">＋</span> Special Purchase</button><div class="save-group"><div id="saveNotice" class="save-notice" role="status" ${(drafts.size||sequenceDraft||formDraft||draftCacheFailure||recoveryConflict)?'':'hidden'}><span class="warning-icon" aria-hidden="true">▲<b>!</b></span><span id="saveNoticeText">有未保存修改 / Unsaved changes</span></div><button class="btn primary unified-save" id="saveEdits" ${(drafts.size||sequenceDraft)?'':'disabled'}>Save</button></div><span class="count" id="visibleCount">${shown.length} / ${rows.length} rows · 点击圆圈高亮3秒</span></div><section class="panel"><div class="panelhead"><h2>Purchase Tasks · ${rows.length}</h2><span class="muted">NET自动计算 · 示例EA</span></div><div class="selection"><span id="selectedLabel">${selected.size} selected / 已选</span><div class="actions"><button class="btn" id="moveSelected">Move selected ↕</button><button class="btn" id="saveOrder" ${sequenceDraft?'':'disabled'}>Save row order</button><button class="btn" id="cancelOrder" ${sequenceDraft?'':'disabled'}>Cancel move</button><button class="btn" id="savePrices" ${drafts.size?'':'disabled'}>Save price edits</button><button class="btn" id="cancelPrices" ${drafts.size?'':'disabled'}>Cancel edits</button></div></div><div class="tablewrap"><table><colgroup>${[3.5,2.5,6,7,23,8,5,4.5,4.5,4.5,4.5,4.5,4.5,7,8,3].map(w=>`<col style="width:${w}%">`).join('')}</colgroup><thead><tr>${['<button class="btn" id="clearSelection">Clear</button>','Row','Order Received','Waiting','Description','Supplier','Qty','LP/Pc','LP/Ctn','Disc.1','Disc.2','Disc.3','Net Cost','Our P.O. No.','Path','GP'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody id="taskRows">${rowMarkup(shown)}</tbody></table></div><div class="foot"><span>任务ID固定 · 按圈未完成数不可相加</span><span>示例保存：此浏览器 · 原始客户数量不受实收影响</span></div></section><div class="hint">Purchase只执行自己的动作；其它部门任务可查看与跟进。计算器使用隐藏示例EA，尚未连接Pointbase；价格保存不代表已经完成采购步骤。</div>`;fitItemNames();updateSaveNotice();}

function fitItemNames(){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');for(const el of document.querySelectorAll('#taskRows .itemname')){const name=el.dataset.name,packing=el.dataset.packing,full=name+' · '+packing,width=el.clientWidth;if(!width)continue;const style=getComputedStyle(el),regular='400 '+style.fontSize+' '+style.fontFamily,bold='700 '+style.fontSize+' '+style.fontFamily;const measure=(start,end)=>{let size=0;for(let i=start;i<end;i++){ctx.font=i<name.length?bold:regular;size+=ctx.measureText(full[i]).width;}return size;};let firstEnd=full.length;for(let i=1;i<=full.length;i++)if(measure(0,i)>width){firstEnd=i-1;const space=full.lastIndexOf(' ',firstEnd);if(space>0)firstEnd=space;break;}let lastEnd=full.length,truncated=false;if(firstEnd<full.length){ctx.font=regular;const dots=ctx.measureText('…').width;for(let i=firstEnd+1;i<=full.length;i++)if(measure(firstEnd,i)+dots>width/2){lastEnd=i-1;truncated=true;break;}}const part=(a,b)=>{const split=Math.max(a,Math.min(b,name.length));return esc(full.slice(a,split))+'<span class="packing">'+esc(full.slice(split,b))+'</span>';};el.innerHTML=part(0,firstEnd)+(firstEnd<full.length?'<br>'+part(firstEnd,lastEnd)+(truncated?'…':''):'');}}
function rowMarkup(rows){return rows.map(t=>{const i=next(t),s=stages[i],latest=[...t.history].sort((a,b)=>new Date(b.at)-new Date(a.at))[0],values=[...price(t)],result=costResult(values,t.ea,priceBasis(t));if(!drafts.has(t.id)||priceBasis(t)==='pc')values[1]=result.b===null?'—':result.b.toFixed(2);if(!drafts.has(t.id)&&validatePrice(values[4],4))values[4]=formatPrice(values[4],4);return `<tr data-id="${t.id}" class="${selected.has(t.id)?'selected':''} ${t.special?'special-row':''}"><td><div class="row-controls"><button class="handle" draggable="true" data-drag="${t.id}" aria-label="Move ${t.id}">⠿</button><input class="check rowcheck" type="checkbox" data-id="${t.id}" aria-label="Select ${t.id}" ${selected.has(t.id)?'checked':''}></div></td><td class="row-number">${rowNumber(t.id)}</td><td>${receivedMarkup(t)}</td><td><button class="mission" data-waiting="${t.id}">${s?i===0?'Enter P.O. No.':s[0]:'Completed'}</button></td><td><span class="barcode">${t.barcode}${t.special?'<span class="special-badge">Special Purchase</span>':''}</span><b class="itemname" data-name="${esc(t.name)}" data-packing="${esc(t.packing)}">${esc(t.name)} <span class="packing">${esc(t.packing)}</span></b></td><td><select class="supplier" data-supplier="${t.id}" ${t.po?'disabled':''} aria-label="Supplier ${t.id}">${supplierOptions(t)}</select></td><td><div class="qty-pair"><button class="qty-order" data-qty="${t.id}" aria-label="Order quantity ${t.id}">${t.ord}</button><span aria-hidden="true">|</span><button class="${t.inc==null?'qty-empty':t.inc===t.ord?'qty-match':'qty-mismatch'}" data-receipt="${t.id}" aria-label="Incoming quantity ${t.id}">${t.inc??'—'}</button></div></td>${values.map((v,j)=>`<td><input class="money ${drafts.has(t.id)&&!(j===0&&!v.trim())&&!validatePrice(v,j)?'invalid':''}" data-price="${t.id}" data-field="${j}" aria-label="${['LP/Pc','LP/Ctn','DISC1','DISC2','DISC3'][j]} ${t.id}" value="${esc(v)}"  inputmode="decimal"></td>`).join('')}<td><b class="net ${result.f!==null&&result.f<0?'negative':''}">${result.f===null?'—':result.f.toFixed(2)}</b></td><td><div class="po"><input class="po-field" data-po="${t.id}" aria-label="PO field ${t.id}" value="${esc(t.po)}" placeholder="P.O. number" readonly></div></td><td><button class="path" data-path="${t.id}"><strong>${esc(latest.kind)} on</strong><br>${fullDate(latest.at)} by ${esc(latest.by)}</button>${t.risk?`<button class="risk" data-risk="${t.id}">● Risk</button>`:t.wasRisk&&t.inc===t.ord?'<span class="good">Problem Solved</span>':''}</td><td><b class="gp ${projectedGp(t)!==null&&projectedGp(t)<0?'negative':''}">${gpMarkup(t)}</b></td></tr>`;}).join('')||'<tr><td colspan="16" class="empty">No matching tasks / 没有匹配的任务</td></tr>';}
function renderPo(){const groups=new Map();for(const t of active().filter(t=>t.po)){if(!groups.has(t.po))groups.set(t.po,[]);groups.get(t.po).push(t);}app.innerHTML=heading('Purchase Order','外部供应商采购单 · 只登记关联，不开正式单据')+`<section class="panel"><table class="directory"><thead><tr><th>P.O. Number</th><th>Tasks / 产品任务</th><th>ord / CTN</th><th>Supplier</th><th></th></tr></thead><tbody>${[...groups].map(([po,rows])=>`<tr><td><b>${esc(po)}</b></td><td>${rows.length}</td><td>${rows.reduce((n,t)=>n+t.ord,0)}</td><td>${[...new Set(rows.map(t=>t.supplier))].join(', ')}</td><td><button class="btn" data-po-details="${esc(po)}">Details ↗</button></td></tr>`).join('')}</tbody></table></section>`;}
function renderPayments(){app.innerHTML=heading('Payment Follow-up','Account负责付款，Purchase仅跟进 · 每次申请独立')+`<section class="panel"><table class="directory"><thead><tr><th>Request ID</th><th>P.O.</th><th>Requested</th><th>Paid</th><th>Balance</th><th>Urgent / 催款</th><th></th></tr></thead><tbody>${db.paymentRequests.map(p=>`<tr><td>${p.id}</td><td>${p.po}</td><td>${p.currency} ${p.amount.toFixed(2)}</td><td>${p.paid.toFixed(2)}</td><td>${(p.amount-p.paid).toFixed(2)}</td><td>${p.urgent?'<span class="bubble">待跟进</span>':'—'}</td><td><button class="btn" data-payment="${p.id}">Details</button></td></tr>`).join('')}</tbody></table></section>`;}
function renderHistory(){const events=db.tasks.flatMap(t=>t.history.map(e=>({...e,taskId:t.id,customerId:t.customerId}))).sort((a,b)=>new Date(b.at)-new Date(a.at));app.innerHTML=heading('Activity History','示例动作记录 · 首次时间与后续动作分别保留')+`<section class="panel"><table class="directory"><thead><tr><th>Task</th><th>Action</th><th>Time / Actor</th><th>Detail</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td>${e.taskId}</td><td>${esc(e.kind)}</td><td>${fullDate(e.at)} by ${esc(e.by)}</td><td>${esc(e.detail)}</td><td><button class="btn" data-path="${e.taskId}">PATH</button></td></tr>`).join('')}</tbody></table></section>`;}
function openDialog(title,sub,body,buttons='',onSave=null){clearHold();content.innerHTML=`<div class="dialoghead"><div><div class="eyebrow">LOCAL UX · 示例操作</div><h2>${title}</h2><span class="muted">${companyCode} · ${sub}</span></div><button class="close" id="closeDialog" aria-label="Close">×</button></div><div class="dialogbody">${body}<div class="error" id="dialogError" role="alert"></div></div><div class="dialogfoot"><span class="muted">不连接真实数据</span><div class="actions"><button class="btn" id="cancelDialog">${onSave?'Cancel':'Close'}</button>${buttons}</div></div>`;modal.showModal();content.querySelector('#closeDialog').onclick=closeDialog;content.querySelector('#cancelDialog').onclick=closeDialog;if(onSave)content.querySelector('#dialogSave').onclick=onSave;}
function closeDialog(){modal.close();modal.classList.remove('special-dialog','supplier-dialog');supplierFormOpen=false;content.innerHTML='';dropFormDraft();}function error(m){content.querySelector('#dialogError').textContent=m;}
function listRows(rows){return `<table class="rowlist"><colgroup><col style="width:25%"><col style="width:55%"><col style="width:20%"></colgroup><thead><tr><th>BARCODE</th><th>DESCRIPTION</th><th>QTY · ord</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${t.barcode}<small>${t.id}</small></td><td><b>${t.name}</b><small>${t.packing}</small></td><td>${t.ord} CTN</td></tr>`).join('')}</tbody></table>`;}
function openPo(id){if(drafts.size||sequenceDraft){toast('请先点击Save保存价格/排列编辑。');return;}if(selected.size&&!selected.has(id)){toast('请点击已勾选行的P.O.输入框，或先清除选择。');return;}const rows=selected.size?scope().filter(t=>selected.has(t.id)):[find(id)];if(new Set(rows.map(t=>t.customerId)).size!==1||new Set(rows.map(t=>supplier(t))).size!==1||rows.some(t=>!supplier(t))){toast('一张P.O.只能关联同一客户、同一供应商；请重新选择。');return;}const currentPo=[...new Set(rows.map(t=>t.po))],prefill=currentPo.length===1?currentPo[0]:'';setFormContext('po',id,rows.map(t=>t.id));openDialog('Purchase Order / 编辑与关联采购单',`${rows.length} selected tasks · ${rows.reduce((n,t)=>n+t.ord,0)} CTN`,listRows(rows)+`<div class="note">${[...new Set(rows.map(t=>t.supplier))].join(' / ')} · 每行任务ID保留${rows.some(t=>t.po)?'<br>当前号码：'+rows.map(t=>esc(t.id)+' → '+esc(t.po||'未登记')).join('<br>'):''}</div><div class="field"><label>P.O. NUMBER *</label><input id="poNumber" maxlength="80" value="${esc(prefill)}" placeholder="Enter supplier P.O. number"></div>`,'<button class="btn primary" id="dialogSave">Merge / Save</button>',()=>{const po=content.querySelector('#poNumber').value.trim();if(!po)return error('请输入P.O.号码。');const existing=db.tasks.filter(t=>t.po&&t.po.trim().toUpperCase()===po.toUpperCase());if(existing.some(t=>t.customerId!==rows[0].customerId||t.supplier!==supplier(rows[0]))){return error('此P.O.号码已属于其他供应商或客户，请使用正确的采购单号码。');}if(new Set(rows.map(t=>t.supplier)).size>1)return error('已选任务包含不同供应商。此关联规则待确认，请先选择同一供应商。');const changed=rows.filter(t=>t.po!==po);if(!changed.length)return error('P.O.号码没有变化。');for(const row of changed){const t=find(row.id),previous=t.po;t.po=po;t.done[0]=true;event(t,previous?'PO Updated':'PO merged',`${previous?previous+' → ':''}${po} · ${rows.length} independent tasks linked`);}if(!persist())return;closeDialog();render();toast(`示例已保存：${rows.length}行关联${po}，任务ID保留。`);});}
function pathDialog(id){const t=find(id),hist=[...t.history].sort((a,b)=>new Date(b.at)-new Date(a.at));openDialog('PATH',`${t.id} · ${t.barcode} · ${t.name}`,`<div class="timeline">${hist.map(e=>`<div class="event"><b>${esc(e.kind)}</b><small>on ${fullDate(e.at)} by ${esc(e.by)}</small><p>${esc(e.detail)}</p></div>`).join('')}</div>${t.risk?'<div class="notice">仍为Risk：ord '+t.ord+' / inc '+t.inc+'。实收记录不等于已收齐。</div>':''}`);}
function riskDialog(id){let t=find(id);if(!t.risk){pathDialog(id);return;}setFormContext('risk',id);const reasons=['Supplier short delivery / 供应商少送','Supplier excess delivery / 供应商多送','Damaged goods / 货损','Wrong items / 货不对版','Other / 其它'];openDialog('Receipt Risk',`${t.barcode} · ${t.name}`,`<div class="stats"><div><span>ord</span><b>${t.ord}</b></div><div><span>inc · cumulative</span><b>${t.inc}</b></div><div class="red"><span>Difference</span><b>${t.inc-t.ord}</b></div></div><div class="field"><label>Reason *</label><select id="riskReason"><option value="">选择原因</option>${reasons.map(r=>`<option ${t.risk.reason===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Additional note</label><textarea id="riskNote">${esc(t.risk.note)}</textarea></div><span class="badgeblue">Sales Room</span> <span class="badgeblue">Account Room</span><div class="notice" style="margin-top:15px">补送预期仍是Risk。后续累计补齐才Problem Solved；不修改客户Committed Qty。</div>`,'<button class="btn danger" id="dialogSave">Send Note</button>',()=>{t=find(id);const reason=content.querySelector('#riskReason').value,note=content.querySelector('#riskNote').value.trim();if(!reason)return error('请选择Risk原因。');t.risk={reason,note};t.wasRisk=true;event(t,'Risk Note Sent',`${reason} · ${note} · Sales Room + Account Room（示例通知）`);if(!persist())return;closeDialog();render();toast('示例通知已记录；未发送给真实Sales／Account。');});}
function actionDialog(id){let t=find(id);const i=next(t),s=stages[i];if(!s)return pathDialog(id);if(i===0)return openPo(id);if(s[4]!=='Purchase')return openDialog(s[0]+' / '+s[1],t.id,`<p>${s[3]}由 <b>${s[4]}</b> 在自己的Room操作。</p><div class="note">Purchase可跟进，但不能代替此部门执行。此步骤尚未完成，仍计入待办。</div>`);if(i===4)openDialog('Acknowledge Payment / 确认付款通知',t.id,`<p>查看Account回报后，记录采购员Noted。</p><div class="note">这是示例已有付款记录；部分付款与真实回报的规则在数据接入时另行核实。</div>`,'<button class="btn primary" id="dialogSave">Noted</button>',()=>{t=find(id);t.done[4]=true;event(t,'Payment Noted','Purchase acknowledged sample payment');if(!persist())return;closeDialog();render();toast('示例采购确认已记录。');});}
function qtyDialog(id){let t=find(id);setFormContext('qty',id);openDialog('Order Qty / 订单数量',`${t.id} · Requested Qty ${t.requested} CTN`,`${t.risk?'<div class="notice">此行有Risk。调整ord不解除Risk，不代替后续补送。</div>':''}<div class="field"><label>ord *</label><input id="qtyValue" type="number" min="0" step="1" value="${t.ord}"></div><div class="field"><label>Reason *</label><textarea id="qtyReason"></textarea></div>`,'<button class="btn primary" id="dialogSave">SAVE</button>',()=>{t=find(id);const raw=content.querySelector('#qtyValue').value,n=Number(raw),reason=content.querySelector('#qtyReason').value.trim();if(!raw||!Number.isInteger(n)||n<0)return error('请输入非负整数数量。');if(!reason)return error('数量调整必须填写Reason。');if(n===t.ord)return error('数量没有变化。');const previous=t.ord;t.ord=n;event(t,'Order Qty Updated',`${previous} → ${n} CTN · Reason: ${reason} · Requested ${t.requested} unchanged`);if(!persist())return;closeDialog();render();toast('示例ord已保存；没有回传真实Buyer／Sales。');});}
function receiptDialog(id){const t=find(id);openDialog('Incoming Qty / 实收记录',`${t.id} · Warehouse负责`,`${listRows([t])}<div class="stats"><div><span>ord</span><b>${t.ord}</b></div><div><span>inc · cumulative received</span><b>${t.inc??'—'}</b></div></div><div class="note">实收由Warehouse在自己的Room登记。Purchase原型提供只读查看与Risk通知，不提供代录仓库数量按钮。</div>${t.risk?'<div class="notice">当前Risk，后续累计补齐才解决。</div>':''}`);}
function moveDialog(){if(!selected.size)return toast('先勾选要移动的行。');setFormContext('move',null,[...selected]);openDialog('Move selected tasks / 移动已选任务',`${selected.size} selected · IDs retained`,`<div class="field"><label>Destination</label><select id="moveTarget"><option value="top">Top / 移到顶部</option><option value="bottom">Bottom / 移到底部</option>${scope().filter(t=>!selected.has(t.id)).map(t=>`<option value="${t.id}">Before ${t.id} · ${t.name}</option>`).join('')}</select></div><div class="note">仅调整排列，稍后点击Save。Buyer／Sales顺序不会改变。</div>`,'<button class="btn primary" id="dialogSave">Apply move</button>',()=>{if(!sequenceDraft)sequenceDraft=scope().map(t=>t.id);const all=scope(),moving=all.filter(t=>selected.has(t.id)),rest=all.filter(t=>!selected.has(t.id)),target=content.querySelector('#moveTarget').value,pos=target==='top'?0:target==='bottom'?rest.length:rest.findIndex(t=>t.id===target);rest.splice(pos,0,...moving);rest.forEach((t,i)=>t.seq=i);closeDialog();renderRoom();toast('示例排列已调整，点击Save保存。');});}
function validatePrice(v,i){const s=v.trim();if(i<2)return /^\d+(\.\d{1,2})?$/.test(s);if(i<4)return /^\d+(\.\d{1,2})?%?$/.test(s)&&parseFloat(s)<=100;return /^\d+(\.0{1,2})?$/.test(s);}
function formatPrice(v,i){return i<2?Number(v).toFixed(2):i<4?parseFloat(v).toFixed(2)+'%':Number(v).toFixed(2);}
function draft(id){if(!drafts.has(id)){const t=find(id);const values=[...t.price],r=costResult(values,t.ea,t.priceBasis||'ctn');values[1]=r.b===null?'':r.b.toFixed(2);if(validatePrice(values[4],4))values[4]=formatPrice(values[4],4);drafts.set(id,{price:values,supplier:t.supplier,priceBasis:t.priceBasis||'ctn',base:taskDraftBase(t)});}return drafts.get(id);}
function savePrices(){for(const [id,d]of drafts){if(d.price[0].trim()&&!validatePrice(d.price[0],0)){toast(`${id}：LP/PC须为两位小数或留空。`);return;}const r=costResult(d.price,find(id).ea,d.priceBasis);if(r.f===null){toast(`${id}：请输入LP/CTN，或提供LP/PC及EA；Disc.1/2须为0–100%，Disc.3须为整数。`);return;}}for(const [id,d]of drafts){const t=find(id),r=costResult(d.price,t.ea,d.priceBasis);t.price=d.price.map((v,i)=>i===0&&!v.trim()?'':i===1?r.b.toFixed(2):formatPrice(v,i));t.priceBasis=d.priceBasis;t.supplier=d.supplier;event(t,'Price Inputs Saved',`Calculator inputs saved · ${d.priceBasis==='pc'?'EA × LP/PC':'Entered LP/CTN'} · sequential percentages then Disc.3`);}if(!persist())return;drafts.clear();restoredDraft=false;saveDraftCache();render();toast('示例计算器已保存；EA仍为示例值。');}
function navigate(target,cid){if(drafts.size||sequenceDraft){openDialog('Unsaved edits / 未保存编辑','先完成当前编辑',`<p>请先保存或取消价格／排列编辑，再切换页面或客户。</p>`);return;}if(cid&&cid!==customerId){customerId=cid;selected.clear();filter={query:'',supplier:'',order:'',stage:'',risk:false};}view=target;render();updateCompanyHeader();}
function clearHold(){clearTimeout(highlightTimer);held=null;document.querySelectorAll('tr.highlight').forEach(r=>r.classList.remove('highlight'));}
function hold(i){clearTimeout(highlightTimer);held=i;document.querySelectorAll('tr[data-id]').forEach(r=>r.classList.toggle('highlight',unfinished(find(r.dataset.id),i)));if(view==='room')document.querySelector('#visibleCount').textContent=`${matching().filter(t=>unfinished(t,i)).length} visible matches · ${counts(scope())[i]} total pending · 3秒后恢复`;highlightTimer=setTimeout(release,3000);}function release(){clearHold();const count=document.querySelector('#visibleCount');if(count)count.textContent=`${matching().length} / ${scope().length} rows · 点击圆圈高亮3秒`;}
document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-drag]');if(handle)handle.closest('tr').classList.add('grip-down');});document.addEventListener('pointerup',clearDragFeedback);document.addEventListener('pointercancel',clearDragFeedback);window.addEventListener('blur',()=>{release();clearDragFeedback();});document.addEventListener('visibilitychange',release);document.addEventListener('keydown',e=>{const c=e.target.closest('[data-hold]');if(c&&[' ','Enter'].includes(e.key)){e.preventDefault();hold(Number(c.dataset.hold));}});
function clearDragFeedback(){document.querySelectorAll('.grip-down,.dragging-row,.drop-target').forEach(r=>r.classList.remove('grip-down','dragging-row','drop-target'));}
function waitingTip(id,anchor){document.querySelector('#waitingTip')?.remove();const t=find(id),i=next(t),s=stages[i];if(!s)return pathDialog(id);const tip=document.createElement('div');tip.id='waitingTip';tip.className='waiting-tip';tip.setAttribute('role','status');tip.innerHTML=`<b>${i===0?'此行订单正在等待Purchaser输入P.O.号码。':`此行订单正在等待${s[4]}${s[3]}。`}</b><span>${i===0?'This task is waiting for the Purchaser to enter a supplier P.O. number.':`${s[4]}: ${s[2]}.`}</span>${i===4?`<button class="btn primary" data-action="${t.id}">Noted</button>`:''}`;document.body.append(tip);const r=anchor.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(r.left,innerWidth-tip.offsetWidth-8))+'px';tip.style.top=Math.min(r.bottom+5,innerHeight-tip.offsetHeight-8)+'px';}
document.addEventListener('click',e=>{if(!e.target.closest('#waitingTip'))document.querySelector('#waitingTip')?.remove();const poInput=e.target.closest('input[data-po]');if(poInput)return openPo(poInput.dataset.po);const b=e.target.closest('button');if(!b)return;if(b.dataset.shipment)return shipmentDatesDialog(b.dataset.shipment);if(b.dataset.hold)return hold(Number(b.dataset.hold));if(b.dataset.waiting)return waitingTip(b.dataset.waiting,b);if(b.dataset.view)return navigate(b.dataset.view);if(b.dataset.customer)return navigate('room',b.dataset.customer);if(b.dataset.po)return openPo(b.dataset.po);if(b.dataset.path)return pathDialog(b.dataset.path);if(b.dataset.risk)return riskDialog(b.dataset.risk);if(b.dataset.action)return actionDialog(b.dataset.action);if(b.dataset.qty)return qtyDialog(b.dataset.qty);if(b.dataset.receipt)return receiptDialog(b.dataset.receipt);if(b.dataset.poDetails){const rows=active().filter(t=>t.po===b.dataset.poDetails);return openDialog('Supplier P.O. '+esc(b.dataset.poDetails),`${rows.length} independent tasks`,listRows(rows));}if(b.dataset.payment){const p=db.paymentRequests.find(p=>p.id===b.dataset.payment);return openDialog(p.id,'Account操作 · Purchase只读',`<div class="stats"><div><span>Requested</span><b>${p.amount}</b></div><div><span>Paid</span><b>${p.paid}</b></div><div><span>Balance</span><b>${p.amount-p.paid}</b></div></div><div class="note">${esc(p.reason)||'普通付款申请'}<br>同P.O.的每次申请独立，部分付款不代表全部付清。</div>`);}switch(b.id){case'reviewDraftCache':reviewDraftCache();break;case'specialPurchase':specialDialog();break;case'clearSelection':selected.clear();renderRoom();break;case'riskFilter':riskSummary();break;case'moveSelected':moveDialog();break;case'saveOrder':{for(const t of scope())if(sequenceDraft?.indexOf(t.id)!==t.seq)event(t,'Row Position Updated','Purchase排列已保存 · ID/数量/P.O.保留');const movedSequence=scope().map(t=>t.id),previousSequence=sequenceDraft;sequenceDraft=null;if(!persist()){sequenceDraft=previousSequence;movedSequence.forEach((id,i)=>find(id).seq=i);return;}restoredDraft=false;saveDraftCache();renderRoom();toast('示例排列已保存；真实其它部门未连接。');break;}case'cancelOrder':if(sequenceDraft)sequenceDraft.forEach((id,i)=>find(id).seq=i);sequenceDraft=null;saveDraftCache();renderRoom();break;case'saveEdits':if(drafts.size)savePrices();if(!drafts.size&&sequenceDraft)document.querySelector('#saveOrder').click();break;case'savePrices':savePrices();break;case'cancelPrices':drafts.clear();saveDraftCache();renderRoom();break;case'reset':openDialog('Reset demo / 重置示例','只重置本地示例',`<p>清除本浏览器中的演示编辑，回到初始30任务／5条已登记P.O.。</p>`,'<button class="btn primary" id="dialogSave">Reset</button>',()=>{db=seedCompany();drafts.clear();selected.clear();sequenceDraft=null;recoveryConflict=null;formDraft=null;saveDraftCache();if(!persist())return;closeDialog();render();toast('示例已重置。');});break;}});
document.addEventListener('change',e=>{const el=e.target;if(el.classList.contains('rowcheck')){el.checked?selected.add(el.dataset.id):selected.delete(el.dataset.id);el.closest('tr').classList.toggle('selected',el.checked);document.querySelector('#selectedLabel').textContent=`${selected.size} selected / 已选`;return;}if(el.id==='selectVisible'){matching().forEach(t=>el.checked?selected.add(t.id):selected.delete(t.id));renderRoom();return;}if(el.dataset.supplier){if(find(el.dataset.supplier).po){el.value=find(el.dataset.supplier).supplier;return toast('已关联P.O.的供应商不能直接修改。');}draft(el.dataset.supplier).supplier=el.value;document.querySelector('#savePrices').disabled=false;document.querySelector('#cancelPrices').disabled=false;document.querySelector('#saveEdits').disabled=false;restoredDraft=false;saveDraftCache();return;}const ids={supplierFilter:'supplier',orderFilter:'order',stageFilter:'stage'};if(ids[el.id]){filter[ids[el.id]]=el.value;renderRoom();}});
document.addEventListener('input',e=>{const el=e.target;if(modal.open&&content.contains(el)){captureFormDraft();const message=content.querySelector('#dialogError');if(message)message.textContent='';}if(el.dataset.price){el.dataset.focusEdited='1';const d=draft(el.dataset.price),field=Number(el.dataset.field);d.price[field]=el.value;if(field===0)d.priceBasis=el.value.trim()?'pc':'ctn';if(field===1)d.priceBasis='ctn';el.classList.toggle('invalid',!(Number(el.dataset.field)===0&&!el.value.trim())&&!validatePrice(el.value,Number(el.dataset.field)));refreshCost(el.dataset.price);document.querySelector('#savePrices').disabled=false;document.querySelector('#cancelPrices').disabled=false;document.querySelector('#saveEdits').disabled=false;restoredDraft=false;saveDraftCache();}if(el.id==='search'){filter.query=el.value;release();document.querySelector('#taskRows').innerHTML=rowMarkup(matching());fitItemNames();document.querySelector('#visibleCount').textContent=`${matching().length} / ${scope().length} rows`; }if(el.id==='customerSearch')app.querySelectorAll('tbody tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(el.value.toLowerCase()));});
document.addEventListener('focusin',e=>{const el=e.target;if(el.dataset.price&&!el.readOnly){el.dataset.focusValue=el.value;el.dataset.focusEdited='0';el.value='';}});
document.addEventListener('focusout',e=>{const el=e.target;if(el.dataset.price&&el.dataset.focusEdited==='0'){el.value=el.dataset.focusValue;delete el.dataset.focusValue;delete el.dataset.focusEdited;return;}if(el.matches('[data-hold]'))release();if(el.dataset.price&&!el.readOnly&&drafts.has(el.dataset.price)&&validatePrice(el.value,Number(el.dataset.field))){const v=formatPrice(el.value,Number(el.dataset.field));el.value=v;draft(el.dataset.price).price[Number(el.dataset.field)]=v;refreshCost(el.dataset.price);saveDraftCache();}});
document.addEventListener('dragstart',e=>{const h=e.target.closest('[data-drag]');if(!h)return;dragId=h.dataset.drag;h.closest('tr').classList.add('dragging-row');e.dataTransfer.setData('text/plain',dragId);e.dataTransfer.effectAllowed='move';});document.addEventListener('dragover',e=>{if(dragId&&e.target.closest('tr[data-id]')){e.preventDefault();document.querySelectorAll('.drop-target').forEach(r=>r.classList.remove('drop-target'));e.target.closest('tr').classList.add('drop-target');}});document.addEventListener('drop',e=>{const target=e.target.closest('tr[data-id]');if(!target||!dragId)return;e.preventDefault();if(dragId===target.dataset.id){dragId=null;return;}if(!sequenceDraft)sequenceDraft=scope().map(t=>t.id);const ids=scope().map(t=>t.id);const from=ids.indexOf(dragId),to=ids.indexOf(target.dataset.id);if(from>=0&&to>=0){ids.splice(from,1);ids.splice(ids.indexOf(target.dataset.id),0,dragId);ids.forEach((id,i)=>find(id).seq=i);}dragId=null;clearDragFeedback();saveDraftCache();renderRoom();toast('行已移动，请点击Save保存。');});document.addEventListener('dragend',()=>{dragId=null;clearDragFeedback();});
modal.addEventListener('cancel',()=>{content.innerHTML='';dropFormDraft();});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});window.addEventListener('beforeunload',e=>{saveDraftCache();if(drafts.size||sequenceDraft||formDraft){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{const el=e.target;if(!el.dataset.price||e.isComposing||!['Enter','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const fields=[...document.querySelectorAll('#taskRows [data-price]')],index=fields.indexOf(el),offset=e.key==='Enter'?(e.shiftKey?-1:1):e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:e.key==='ArrowUp'?-5:5,target=fields[index+offset];e.preventDefault();if(target){target.focus();}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveDraftCache();});window.addEventListener('resize',fitItemNames);restoreDraftCache();persist();render();restoreFormDraft();updateSaveNotice();

function specialDialog(){
 if(drafts.size||sequenceDraft){updateSaveNotice('请先点击Save保存当前编辑，再新增特别采购。');return;}
 const rows=scope().filter(t=>!t.special),chosen=selected.size===1?rows.find(t=>selected.has(t.id)):rows[0];
 const source=chosen||rows[0];if(!source)return toast('没有可追加采购的来源产品行。');
 setFormContext('special',source.id);modal.classList.add('special-dialog');
 openDialog('Special Purchase','新增特别采购行',`
 <div class="special-context"><div><span>Customer</span><b>${esc(customerName(db.customers.find(c=>c.id===customerId)))}</b></div><div><span>Supplier</span><b id="specialSupplier">${esc(supplier(source))}</b></div></div>
 <div class="field source-field"><label for="specialSource">Add Item From *</label><select id="specialSource">${rows.map(t=>`<option value="${t.id}" ${t.id===source.id?'selected':''}>Row ${rowNumber(t.id)} · ${esc(t.name)} · ${t.barcode}</option>`).join('')}</select></div>
 <div class="source-product" id="specialProduct"></div>
 <div class="special-qty"><div><span>Original Qty</span><b id="specialOriginal"></b></div><span class="qty-symbol">＋</span><div><label for="specialQty">Extra Qty *</label><div class="extra-input"><input id="specialQty" type="number" min="1" step="1" placeholder="20"><span>CTN</span></div></div><span class="qty-symbol">＝</span><div class="total"><span>Total Purchase</span><b id="specialTotal"></b></div></div>
 <div class="field reason-field"><label for="specialReason">Reason *</label><textarea id="specialReason" placeholder="例如：供应商订满100箱提供更优惠价格，因此追加20箱。"></textarea></div>
 <div class="special-explain">新增行留在 ${esc(customerName(db.customers.find(c=>c.id===customerId)))}，紧接来源行下方。原行数量保留。</div>
 `,'<button class="btn special-button" id="dialogSave">＋ Add</button>',()=>{
  const t=find(content.querySelector('#specialSource').value),raw=content.querySelector('#specialQty').value,n=Number(raw),reason=content.querySelector('#specialReason').value.trim();
  if(!raw||!Number.isInteger(n)||n<=0)return error('请输入大于0的整数追加箱数。');
  if(!reason)return error('请填写特别采购原因。');
  const id='T-SP-'+crypto.randomUUID(),at=now(),seq=t.seq+1;
  scope().filter(x=>x.seq>=seq).forEach(x=>x.seq++);
  const added={...structuredClone(t),id,special:true,sourceTaskId:t.id,ord:n,requested:n,inc:null,po:'',done:Array(9).fill(false),risk:null,wasRisk:false,gp:null,seq,receivedAt:at,updatedAt:at,updatedBy:'Law',history:[{kind:'Special Purchase Added',at,by:'Law',detail:reason+' · Source '+t.id+' · Extra '+n+' CTN'}]};
  db.tasks.push(added);if(!persist())return error('保存失败，请重试。');closeDialog();modal.classList.remove('special-dialog');renderRoom();document.querySelector('tr[data-id="'+id+'"]').scrollIntoView({block:'nearest'});
 });
 function update(){const t=find(content.querySelector('#specialSource').value),n=Number(content.querySelector('#specialQty').value);content.querySelector('#specialSupplier').textContent=supplier(t);content.querySelector('#specialProduct').innerHTML=`<b>${esc(t.name)}</b><span>${esc(t.barcode)} · ${esc(t.packing)}</span>`;content.querySelector('#specialOriginal').textContent=t.ord+' CTN';content.querySelector('#specialTotal').textContent=content.querySelector('#specialQty').value&&Number.isInteger(n)&&n>0?(t.ord+n)+' CTN':'—';}
 content.querySelector('#specialSource').onchange=update;content.querySelector('#specialQty').oninput=update;update();
}
